import DButton from "discourse/ui-kit/d-button";
import DDropdownMenu from "discourse/ui-kit/d-dropdown-menu";
import dIcon from "discourse/ui-kit/helpers/d-icon";

const buttonOptionsMap = {
  exportResults: {
    className: "btn-default export-results",
    label: "poll.export-results.label",
    title: "poll.export-results.title",
    icon: "download",
    action: "exportResults",
  },
  showBreakdown: {
    className: "btn-default show-breakdown",
    label: "poll.breakdown.breakdown",
    icon: "chart-pie",
    action: "showBreakdown",
  },
  openPoll: {
    className: "btn-default toggle-status",
    label: "poll.open.label",
    title: "poll.open.title",
    icon: "unlock-keyhole",
    action: "toggleStatus",
  },
  closePoll: {
    className: "btn-default toggle-status",
    label: "poll.close.label",
    title: "poll.close.title",
    icon: "lock",
    action: "toggleStatus",
  },
  showTally: {
    className: "btn-default show-tally",
    label: "poll.show-tally.label",
    title: "poll.show-tally.title",
    icon: "info",
    action: "toggleDisplayMode",
  },
  showPercentage: {
    className: "btn-default show-percentage",
    label: "poll.show-percentage.label",
    title: "poll.show-percentage.title",
    icon: "info",
    action: "toggleDisplayMode",
  },
};

export default class PollButtonsDropdownComponent extends Component {
  @service currentUser;
  @service siteSettings;

  constructor() {
    super(...arguments);
    this.getDropdownButtonState = false;
  }

  get getDropdownContent() {
    const contents = [];
    const isAdmin = this.currentUser && this.currentUser.admin;

    const dataExplorerEnabled = this.siteSettings.data_explorer_enabled;
    const exportQueryID = this.args.isRankedChoice
      ? this.siteSettings.poll_export_ranked_choice_data_explorer_query_id
      : this.siteSettings.poll_export_data_explorer_query_id;

    const {
      closed,
      voters,
      isStaff,
      isMe,
      topicArchived,
      groupableUserFields,
      isAutomaticallyClosed,
      availableDisplayMode,
    } = this.args;

    if (availableDisplayMode) {
      const option = { ...buttonOptionsMap[availableDisplayMode] };
      option.id = option.action;
      contents.push(option);
    }

    if (groupableUserFields.length && voters > 0) {
      const option = { ...buttonOptionsMap.showBreakdown };
      option.id = option.action;
      contents.push(option);
    }

    if (isAdmin && dataExplorerEnabled && voters > 0 && exportQueryID) {
      const option = { ...buttonOptionsMap.exportResults };
      option.id = option.action;
      contents.push(option);
    }

    if (this.currentUser && (isMe || isStaff) && !topicArchived) {
      if (closed) {
        if (!isAutomaticallyClosed) {
          const option = { ...buttonOptionsMap.openPoll };
          option.id = option.action;
          contents.push(option);
        }
      } else {
        const option = { ...buttonOptionsMap.closePoll };
        option.id = option.action;
        contents.push(option);
      }
    }

    return contents;
  }

  get showDropdown() {
    return this.getDropdownContent.length > 1;
  }

  get showDropdownAsButton() {
    return this.getDropdownContent.length === 1;
  }

  @action
  dropDownClick(dropDownAction) {
    this.args.dropDownClick(dropDownAction);
  }

  <template>
    <div class="poll-buttons-dropdown">
      {{#if this.showDropdown}}
        <DMenu class="widget-dropdown-header">
          <:trigger>
            {{dIcon "gear"}}
          </:trigger>
          <:content>
            <DDropdownMenu as |dropdown|>
              {{#each this.getDropdownContent as |content index|}}
                {{#if index}}
                  <dropdown.divider />
                {{/if}}
                <dropdown.item>
                  <DButton
                    class="widget-button {{content.className}}"
                    @action={{fn this.dropDownClick content.action}}
                    @icon={{content.icon}}
                    @label={{content.label}}
                  />
                </dropdown.item>
              {{/each}}
            </DDropdownMenu>
          </:content>
        </DMenu>
      {{else if this.showDropdownAsButton}}
        <DButton
          class="widget-button {{get this.getDropdownContent '0.className'}}"
          @action={{fn
            this.dropDownClick
            (get this.getDropdownContent "0.action")
          }}
          @icon={{get this.getDropdownContent "0.icon"}}
          @label={{get this.getDropdownContent "0.label"}}
        />
      {{/if}}
    </div>
  </template>
}
import Component from "@glimmer/component";
import { service } from "@ember/service";
import { trustHTML } from "@ember/template";
import { relativeAge } from "discourse/lib/formatter";
import dIcon from "discourse/ui-kit/helpers/d-icon";
import { i18n } from "discourse-i18n";

const ON_VOTE = "on_vote";
const ON_CLOSE = "on_close";
const STAFF_ONLY = "staff_only";

export default class PollInfoComponent extends Component {
  @service currentUser;

  get multipleHelpText() {
    const { min, max, options } = this.args;
    const optionsCount = options.length;

    if (max > 0) {
      if (min === max && min > 1) {
        return trustHTML(i18n("poll.multiple.help.x_options", { count: min }));
      }

      if (min > 1) {
        if (max < optionsCount) {
          return trustHTML(
            i18n("poll.multiple.help.between_min_and_max_options", {
              min,
              max,
            })
          );
        }

        return trustHTML(
          i18n("poll.multiple.help.at_least_min_options", { count: min })
        );
      }

      if (max <= optionsCount) {
        return trustHTML(
          i18n("poll.multiple.help.up_to_max_options", { count: max })
        );
      }
    }
  }

  get votersLabel() {
    return i18n("poll.voters", { count: this.args.voters });
  }

  get showTotalVotes() {
    return this.args.isMultiple && (this.args.showResults || this.args.closed);
  }

  get totalVotes() {
    return this.args.options.reduce((total, o) => {
      return total + parseInt(o.votes, 10);
    }, 0);
  }

  get totalVotesLabel() {
    return i18n("poll.total_votes", { count: this.totalVotes });
  }

  get showAutomaticClose() {
    return (
      this.args.isAutomaticallyClosed ||
      (!!this.args.closesAt && !this.args.closed)
    );
  }

  get automaticCloseLabel() {
    return trustHTML(
      this.args.isAutomaticallyClosed
        ? i18n("poll.automatic_close.age", { age: this.age })
        : i18n("poll.automatic_close.closes_in", { timeLeft: this.timeLeft })
    );
  }

  get showMultipleHelpText() {
    return (
      this.args.isMultiple &&
      !this.args.showResults &&
      !this.args.showingVotedChoices &&
      !this.args.closed
    );
  }

  get closeTitle() {
    return this.args.closesAt?.format("LLL") ?? "";
  }

  get age() {
    return relativeAge(this.args.closesAt.toDate(), { addAgo: true });
  }

  get timeLeft() {
    return moment().to(this.args.closesAt, true);
  }

  get resultsOnVote() {
    return (
      this.args.results === ON_VOTE &&
      !this.args.hasVoted &&
      !(this.currentUser && this.args.postUserId === this.currentUser.id)
    );
  }

  get resultsOnVoteTitle() {
    return trustHTML(i18n("poll.results.vote.title"));
  }

  get resultsOnClose() {
    return this.args.results === ON_CLOSE && !this.args.closed;
  }

  get resultsOnCloseTitle() {
    return trustHTML(i18n("poll.results.closed.title"));
  }

  get resultsStaffOnly() {
    return (
      this.args.results === STAFF_ONLY &&
      !(this.currentUser && this.currentUser.staff)
    );
  }

  get resultsStaffOnlyTitle() {
    return trustHTML(i18n("poll.results.staff.title"));
  }

  get publicTitle() {
    return (
      !this.args.closed &&
      !this.args.showResults &&
      this.args.isPublic &&
      this.args.results !== STAFF_ONLY
    );
  }

  get publicTitleLabel() {
    return trustHTML(i18n("poll.public.title"));
  }

  get showInstructionsSection() {
    return (
      this.args.showingVotedChoices ||
      this.showMultipleHelpText ||
      this.showAutomaticClose ||
      this.args.closedBy ||
      this.resultsOnVote ||
      this.resultsOnClose ||
      this.resultsStaffOnly ||
      this.publicTitle ||
      this.args.isDynamic
